<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useWorkforce} from '../context'
import {usePayrollText} from '../payrollText'
import {ruleOverrides} from '../payrollConfigurationTypes'
import {useWorkforceText} from '../text'
import {usePayrollConfigurationText} from '../payrollConfigurationText'
import {storeToday} from '../time'
import type {EmployeePaySummaryData} from '../payrollConfigurationTypes'
const props=defineProps<{employeeId:string;companyId?:string|null;saved:boolean}>()
const {api,payrollHome,store,current}=useWorkforce(),{error}=useWorkforceText(),{r}=usePayrollText(),{pc}=usePayrollConfigurationText()
const companies=computed(()=>payrollHome?.value?.companies||[]),company=ref(''),on=ref(storeToday()),data=ref<EmployeePaySummaryData|null>(null),loading=ref(false),failure=ref('')
let revision=0
watch(()=>[props.companyId,companies.value] as const,()=>{company.value=companies.value.some(c=>c.id===props.companyId)?props.companyId!:''},{immediate:true})
watch(()=>[props.employeeId,props.saved,company.value,on.value,companies.value] as const,async()=>{const rev=++revision;data.value=null;failure.value='';if(!props.saved||!companies.value.some(c=>c.id===company.value)||!on.value){loading.value=false;return}loading.value=true;try{const result=await api().get<EmployeePaySummaryData>(`/employees/${props.employeeId}/pay-summary?companyId=${company.value}&on=${on.value}`);if(current()&&rev===revision)data.value=result}catch(e){if(current()&&rev===revision)failure.value=error(e)}finally{if(current()&&rev===revision)loading.value=false}},{immediate:true})
const target=computed(()=>({path:`/stores/${store.value}/workforce/pay-profiles/new`,query:{employeeId:props.employeeId,companyId:company.value}}))
</script>
<template><section class="wf-panel"><h2>{{pc('title')}}</h2><p v-if="!saved">{{pc('firstSave')}}</p><p v-else-if="!companies.length">{{pc('restricted')}}</p><template v-else><div class="wf-grid"><label>{{pc('company')}}<select v-model="company"><option value="">—</option><option v-for="c in companies" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>{{pc('on')}}<input v-model="on" type="date"></label></div><p v-if="loading" role="status">…</p><p v-if="failure" role="alert">{{failure}}</p><template v-if="data"><p v-if="!data.profiles.some(p=>p.state==='current')">{{pc('missing')}}</p><article v-for="period in data.profiles" :key="period.profile.id"><h3>{{pc(period.state)}} · {{period.profile.effectiveFrom}} — {{period.effectiveTo||pc('ongoing')}}</h3><p>{{pc('rate')}}: {{period.profile.rule.rate}} · {{r(period.profile.rule.basis)}}</p><p v-if="period.sourceComplete">{{pc('origin')}}: {{period.profile.origin?.templateName}} v{{period.profile.templateVersion}} · {{period.profile.origin?.defaultMappingId?pc('fromDefault')+' v'+period.profile.origin.defaultVersion:pc('personal')}} · {{ruleOverrides(period.profile).length>0?pc('overrides'):pc('unchanged')}}</p><p v-else>{{pc('legacy')}}</p><ul v-if="period.sourceComplete&&ruleOverrides(period.profile).length"><li v-for="key in ruleOverrides(period.profile)" :key="key">{{key==='overtimeMultiplier'?r('multiplier'):key==='items'?r('fixedItems'):key==='generation'?pc('rules'):r(key)}}</li></ul><details><summary>{{pc('rules')}}</summary><p v-for="(item,i) in period.profile.rule.items" :key="i">{{item.label}} · {{item.amount}}</p><p>{{period.profile.rule.overtimeEnabled?'×'+period.profile.rule.overtimeMultiplier:'—'}} · {{period.profile.rule.dayHours}} / {{period.profile.rule.weekHours}}</p><p>{{pc('payment')}}: {{period.profile.payment?r(period.profile.payment.method):'—'}} {{period.profile.payment?.bank}}</p></details><RouterLink target="_blank" rel="noopener" :title="pc('newTab')" :to="{path:`/stores/${store}/workforce/pay-profiles/${period.profile.id}`,query:{companyId:company,employeeId}}">{{pc('edit')}}</RouterLink></article></template><p v-if="company" class="wf-hint">{{pc('newTab')}}</p><RouterLink v-if="company" target="_blank" rel="noopener" :to="target">{{pc('new')}}</RouterLink></template></section></template>
